Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
net: bcmasp: fix double free of WoL irq

We do not need to free wol_irq since it was instantiated with
devm_request_irq(). So devres will free for us.

Fixes: a2f0751206b0 ("net: bcmasp: Add support for WoL magic packet")
Signed-off-by: Justin Chen <justin.chen@broadcom.com>
Reviewed-by: Florian Fainelli <florian.fainelli@broadcom.com>
Link: https://patch.msgid.link/20260319234813.1937315-2-justin.chen@broadcom.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The WoL IRQ was allocated using devm_request_irq, which automatically frees the IRQ via devres when the device is removed or probe fails. However, the code also manually called free_irq in bcmasp_wol_irq_destroy, which was invoked on error cleanup and device removal, causing a double free of the IRQ.

Here is the patch:

-static void bcmasp_wol_irq_destroy(struct bcmasp_priv *priv)
-{
-	if (priv->wol_irq > 0)
-		free_irq(priv->wol_irq, priv);
-}
-
 static void bcmasp_eee_fixup(struct bcmasp_intf *intf, bool en)
 {
 	u32 reg, phy_lpi_overwrite;

 	reg = rx_edpkt_core_rl(intf->parent, ASP_EDPKT_SPARE_REG);
 	phy_lpi_overwrite = intf->internal_phy ? ASP_EDPKT_SPARE_REG_EPHY_LPI :
 			    ASP_EDPKT_SPARE_REG_GPHY_LPI;

 	if (en)
 		reg |= phy_lpi_overwrite;
 	else
 		reg &= ~phy_lpi_overwrite;

 	rx_edpkt_core_wl(intf->parent, reg, ASP_EDPKT_SPARE_REG);

 	usleep_range(50, 100);
 }


 static int bcmasp_probe(struct platform_device *pdev)
 {
 	const struct bcmasp_plat_data *pdata;
 	struct device *dev = &pdev->dev;
 	struct device_node *ports_node;
 	struct bcmasp_priv *priv;
 	struct bcmasp_intf *intf;
 	int ret = 0, count = 0;
 	unsigned int i;

 	priv = devm_kzalloc(dev, sizeof(*priv), GFP_KERNEL);
 	if (!priv)
 		return -ENOMEM;

 	priv->irq = platform_get_irq(pdev, 0);
 	if (priv->irq <= 0)
 		return -EINVAL;

 	priv->clk = devm_clk_get_optional_enabled(dev, "sw_asp");
 	if (IS_ERR(priv->clk))
 		return dev_err_probe(dev, PTR_ERR(priv->clk),
 				     "failed to request clock\n");

 	/* Base from parent node */
 	priv->base = devm_platform_ioremap_resource(pdev, 0);
 	if (IS_ERR(priv->base))
 		return dev_err_probe(dev, PTR_ERR(priv->base), "failed to iomap\n");

 	ret = dma_set_mask_and_coherent(&pdev->dev, DMA_BIT_MASK(40));
 	if (ret)
 		return dev_err_probe(dev, ret, "unable to set DMA mask: %d\n", ret);

 	dev_set_drvdata(&pdev->dev, priv);
 	priv->pdev = pdev;
 	spin_lock_init(&priv->mda_lock);
 	spin_lock_init(&priv->clk_lock);
 	mutex_init(&priv->wol_lock);
 	mutex_init(&priv->net_lock);
 	INIT_LIST_HEAD(&priv->intfs);

 	pdata = device_get_match_data(&pdev->dev);
 	if (!pdata)
 		return dev_err_probe(dev, -EINVAL, "unable to find platform data\n");

 	bcmasp_set_pdata(priv, pdata);

 	/* Enable all clocks to ensure successful probing */
 	bcmasp_core_clock_set(priv, ASP_CTRL_CLOCK_CTRL_ASP_ALL_DISABLE, 0);

 	/* Switch to the main clock */
 	priv->core_clock_select(priv, false);

 	bcmasp_intr2_mask_set_all(priv);
 	bcmasp_intr2_clear_all(priv);

 	ret = devm_request_irq(&pdev->dev, priv->irq, bcmasp_isr, 0,
 			       pdev->name, priv);
 	if (ret)
 		return dev_err_probe(dev, ret, "failed to request ASP interrupt: %d", ret);

 	/* Register mdio child nodes */
 	of_platform_populate(dev->of_node, bcmasp_mdio_of_match, NULL, dev);

 	/* ASP specific initialization, Needs to be done regardless of
 	 * how many interfaces come up.
 	 */
 	bcmasp_core_init(priv);

 	priv->mda_filters = devm_kcalloc(dev, priv->num_mda_filters,
 					 sizeof(*priv->mda_filters), GFP_KERNEL);
 	if (!priv->mda_filters)
 		return -ENOMEM;

 	priv->net_filters = devm_kcalloc(dev, priv->num_net_filters,
 					 sizeof(*priv->net_filters), GFP_KERNEL);
 	if (!priv->net_filters)
 		return -ENOMEM;

 	bcmasp_core_init_filters(priv);

 	bcmasp_init_wol(priv);

 	ports_node = of_find_node_by_name(dev->of_node, "ethernet-ports");
 	if (!ports_node) {
 		dev_warn(dev, "No ports found\n");
 		return -EINVAL;
 	}

 	i = 0;
 	for_each_available_child_of_node_scoped(ports_node, intf_node) {
 		intf = bcmasp_interface_create(priv, intf_node, i);
 		if (!intf) {
 			dev_err(dev, "Cannot create eth interface %d\n", i);
 			of_node_put(ports_node);
 			ret = -EINVAL;
 			goto err_cleanup;
 		}
 		list_add_tail(&intf->list, &priv->intfs);
 		i++;
 	}
 	of_node_put(ports_node);

 	/* Drop the clock reference count now and let ndo_open()/ndo_close()
 	 * manage it for us from now on.
 	 */
 	bcmasp_core_clock_set(priv, 0, ASP_CTRL_CLOCK_CTRL_ASP_ALL_DISABLE);

 	clk_disable_unprepare(priv->clk);

 	/* Now do the registration of the network ports which will take care
 	 * of managing the clock properly.
 	 */
 	list_for_each_entry(intf, &priv->intfs, list) {
 		ret = register_netdev(intf->ndev);
 		if (ret) {
 			dev_err(dev, "failed to register net_device: %d\n", ret);
 			goto err_cleanup;
 		}
 		count++;
 	}

 	dev_info(dev, "Initialized %d port(s)\n", count);

 	return ret;

 err_cleanup:
-	bcmasp_wol_irq_destroy(priv);
 	bcmasp_remove_intfs(priv);

 	return ret;
 }

 static void bcmasp_remove(struct platform_device *pdev)
 {
 	struct bcmasp_priv *priv = dev_get_drvdata(&pdev->dev);

 	if (!priv)
 		return;

-	bcmasp_wol_irq_destroy(priv);
 	bcmasp_remove_intfs(priv);
 }



